-- SEDA P4.3 fixed snapshot
-- Generated from the exported seda_lab snapshot.
--
-- Intended for PostgreSQL/docker-entrypoint-initdb.d (psql).
-- It creates seda_p43 if necessary and loads a deterministic dataset.
--
-- Changes with respect to seda_lab:
--   * variable_catalog is renamed to variable.
--   * actuator, allowed_command and allowed_state are omitted.
--   * measurement quality values are normalized to GOOD/BAD.
--   * command, event and alarm were empty in the source snapshot, so fixed
--     representative rows are added for P4.3 querying exercises.
--
-- All timestamps are absolute so P4.3 questions can use fixed date ranges.

SELECT 'CREATE DATABASE seda_p43 OWNER seda'
WHERE NOT EXISTS (SELECT FROM pg_database WHERE datname = 'seda_p43')\gexec

\connect seda_p43

BEGIN;

DROP TABLE IF EXISTS
    "public"."alarm",
    "public"."event",
    "public"."command",
    "public"."state",
    "public"."measurement",
    "public"."sensor",
    "public"."variable",
    "public"."component",
    "public"."plant"
CASCADE;


CREATE TABLE "public"."plant" (
    "id" serial NOT NULL,
    "name" text NOT NULL,
    CONSTRAINT "plant_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "public"."component" (
    "id" serial NOT NULL,
    "plant_id" integer NOT NULL,
    "code" text NOT NULL,
    "name" text NOT NULL,
    "type" text NOT NULL,
    CONSTRAINT "component_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "public"."variable" (
    "id" serial NOT NULL,
    "code" text NOT NULL,
    "name" text NOT NULL,
    "unit" text NOT NULL,
    CONSTRAINT "variable_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "public"."sensor" (
    "id" serial NOT NULL,
    "component_id" integer NOT NULL,
    "variable_id" integer NOT NULL,
    CONSTRAINT "sensor_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "public"."measurement" (
    "id" serial NOT NULL,
    "component_id" integer NOT NULL,
    "variable_id" integer NOT NULL,
    "ts" timestamp NOT NULL,
    "value" double precision NOT NULL,
    "quality" text NOT NULL,
    CONSTRAINT "measurement_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "public"."state" (
    "id" serial NOT NULL,
    "component_id" integer NOT NULL,
    "ts" timestamp NOT NULL,
    "state" text NOT NULL,
    CONSTRAINT "state_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "public"."command" (
    "id" serial NOT NULL,
    "component_id" integer NOT NULL,
    "ts" timestamp NOT NULL,
    "command" text NOT NULL,
    "value" double precision,
    "status" text NOT NULL,
    CONSTRAINT "command_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "public"."event" (
    "id" serial NOT NULL,
    "component_id" integer NOT NULL,
    "ts" timestamp NOT NULL,
    "event" text NOT NULL,
    CONSTRAINT "event_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "public"."alarm" (
    "id" serial NOT NULL,
    "component_id" integer NOT NULL,
    "ts" timestamp NOT NULL,
    "severity" text NOT NULL,
    "code" text NOT NULL,
    "message" text NOT NULL,
    CONSTRAINT "alarm_pkey" PRIMARY KEY ("id")
);










ALTER TABLE ONLY "public"."component"
    ADD CONSTRAINT "component_plant_id_fkey"
    FOREIGN KEY (plant_id) REFERENCES "public"."plant"(id);

ALTER TABLE ONLY "public"."sensor"
    ADD CONSTRAINT "sensor_component_id_fkey"
    FOREIGN KEY (component_id) REFERENCES "public"."component"(id);

ALTER TABLE ONLY "public"."sensor"
    ADD CONSTRAINT "sensor_variable_id_fkey"
    FOREIGN KEY (variable_id) REFERENCES "public"."variable"(id);

ALTER TABLE ONLY "public"."measurement"
    ADD CONSTRAINT "measurement_component_id_fkey"
    FOREIGN KEY (component_id) REFERENCES "public"."component"(id);

ALTER TABLE ONLY "public"."measurement"
    ADD CONSTRAINT "measurement_variable_id_fkey"
    FOREIGN KEY (variable_id) REFERENCES "public"."variable"(id);

ALTER TABLE ONLY "public"."state"
    ADD CONSTRAINT "state_component_id_fkey"
    FOREIGN KEY (component_id) REFERENCES "public"."component"(id);

ALTER TABLE ONLY "public"."command"
    ADD CONSTRAINT "command_component_id_fkey"
    FOREIGN KEY (component_id) REFERENCES "public"."component"(id);

ALTER TABLE ONLY "public"."event"
    ADD CONSTRAINT "event_component_id_fkey"
    FOREIGN KEY (component_id) REFERENCES "public"."component"(id);

ALTER TABLE ONLY "public"."alarm"
    ADD CONSTRAINT "alarm_component_id_fkey"
    FOREIGN KEY (component_id) REFERENCES "public"."component"(id);

CREATE UNIQUE INDEX component_code_key
    ON "public"."component" USING btree (code);

CREATE UNIQUE INDEX variable_code_key
    ON "public"."variable" USING btree (code);

CREATE INDEX idx_measurement_variable_ts
    ON "public"."measurement" (variable_id, ts);

CREATE INDEX idx_state_component_ts
    ON "public"."state" (component_id, ts);

CREATE INDEX idx_command_component_ts
    ON "public"."command" (component_id, ts);

CREATE INDEX idx_event_component_ts
    ON "public"."event" (component_id, ts);

CREATE INDEX idx_alarm_component_ts
    ON "public"."alarm" (component_id, ts);

SELECT setval(pg_get_serial_sequence('public.plant', 'id'),
              COALESCE((SELECT MAX(id) FROM public.plant), 1), true);
SELECT setval(pg_get_serial_sequence('public.component', 'id'),
              COALESCE((SELECT MAX(id) FROM public.component), 1), true);
SELECT setval(pg_get_serial_sequence('public.variable', 'id'),
              COALESCE((SELECT MAX(id) FROM public.variable), 1), true);
SELECT setval(pg_get_serial_sequence('public.sensor', 'id'),
              COALESCE((SELECT MAX(id) FROM public.sensor), 1), true);
SELECT setval(pg_get_serial_sequence('public.measurement', 'id'),
              COALESCE((SELECT MAX(id) FROM public.measurement), 1), true);
SELECT setval(pg_get_serial_sequence('public.state', 'id'),
              COALESCE((SELECT MAX(id) FROM public.state), 1), true);
SELECT setval(pg_get_serial_sequence('public.command', 'id'),
              COALESCE((SELECT MAX(id) FROM public.command), 1), true);
SELECT setval(pg_get_serial_sequence('public.event', 'id'),
              COALESCE((SELECT MAX(id) FROM public.event), 1), true);
SELECT setval(pg_get_serial_sequence('public.alarm', 'id'),
              COALESCE((SELECT MAX(id) FROM public.alarm), 1), true);

COMMIT;
